findRegex:
/(?=<style>
/\* 引入可爱字体 \*/
@import url\('https://fonts\.googleapis\.com/css2\?family=M\+PLUS\+Rounded\+1c:wght@400;700&display=swap'\);

/\* 最外层容器 \*/
\.konata-thinking-wrapper \{
    display: block;
    margin: 10px 0;
    font-family: 'M PLUS Rounded 1c', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', 'Noto Sans SC', 'PingFang SC', 'Microsoft YaHei', sans-serif;
\}

/\* details 主容器 \*/
\.konata-thinking-details \{
    background-color: #FFF9FA;
    border: 1\.5px solid #FBCFE8;
    border-radius: 22px;
    overflow: hidden;
    box-shadow: 0 8px 25px -8px rgba\(244, 114, 182, 0\.3\);
    transition: box-shadow 0\.3s ease, transform 0\.3s ease;
    position: relative;
\}

\.konata-thinking-details:hover \{
    transform: translateY\(-2px\);
\}

\.konata-thinking-details\[open\] \{
    box-shadow: 0 12px 35px -5px rgba\(244, 114, 182, 0\.4\);
\}

/\* 气泡背景容器 \*/
\.konata-particles-bg \{
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
    overflow: hidden;
    z-index: 1;
    opacity: 0;
    transition: opacity 0\.3s ease;
\}

\.konata-thinking-details\[open\] \.konata-particles-bg \{
    opacity: 1;
\}

/\* 气泡样式 \*/
\.konata-bubble \{
    position: absolute;
    bottom: -150px;
    border-radius: 50%;
    opacity: 0;
    will-change: transform, opacity;
    animation: konataRise 15s linear infinite;
    filter: blur\(1px\);
\}

@keyframes konataRise \{
    0% \{ transform: translate3d\(0, 0, 0\) scale\(0\.7\); opacity: 0; \}
    10% \{ opacity: 0\.7; \}
    50% \{ transform: translate3d\(var\(--sway-x, 20px\), -50vh, 0\) scale\(1\.1\); opacity: 0\.9; \}
    90% \{ opacity: 0\.4; \}
    100% \{ transform: translate3d\(var\(--sway-x-end, -20px\), -110vh, 0\) scale\(0\.6\); opacity: 0; \}
\}

/\* summary 标题栏 \*/
\.konata-thinking-summary \{
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 16px 22px;
    background-color: #FEEFF4;
    border-bottom: 1\.5px solid #FBCFE8;
    cursor: pointer;
    user-select: none;
    list-style: none;
    position: relative;
    z-index: 2;
    transition: background-color 0\.3s ease;
    color: #584964;
    font-weight: 700;
    font-size: 15px;
\}

\.konata-thinking-summary::-webkit-details-marker,
\.konata-thinking-summary::marker \{
    display: none;
\}

\.konata-thinking-summary:hover \{
    background-color: #FDE7F0;
\}

/\* 标题文字部分 \*/
\.konata-title-content \{
    display: flex;
    align-items: center;
    gap: 8px;
\}

/\* 跳动的小桃心 \*/
\.konata-heart \{
    display: inline-block;
    font-size: 16px;
    animation: konataHeartbeat 1\.5s ease-in-out infinite;
    color: #F472B6;
\}

@keyframes konataHeartbeat \{
    0%, 100% \{ transform: scale\(1\); \}
    10% \{ transform: scale\(1\.2\); \}
    20% \{ transform: scale\(1\); \}
    30% \{ transform: scale\(1\.15\); \}
    40% \{ transform: scale\(1\); \}
\}

/\* 展开/收起图标 \*/
\.konata-thinking-summary::after \{
    content: '⌄';
    font-size: 24px;
    font-weight: 300;
    color: #F472B6;
    transition: transform 0\.3s cubic-bezier\(0\.68, -0\.55, 0\.265, 1\.55\), color 0\.3s ease;
    line-height: 1;
\}

\.konata-thinking-summary:hover::after \{
    color: #F9A8D4;
\}

\.konata-thinking-details\[open\] \.konata-thinking-summary::after \{
    transform: rotate\(180deg\) scale\(1\.1\);
    color: #F9A8D4;
\}

/\* 内容区域 - 完整的 Markdown 样式支持 \*/
\.konata-thinking-content \{
    position: relative;
    z-index: 2;
    padding: 14px 18px;
    max-height: 350px;
    overflow-y: auto;
    overflow-x: hidden;
    color: #6D5B79;
    font-size: 13\.5px;
    line-height: 1\.7;
    white-space: pre-wrap;
    word-wrap: break-word;
    animation: konataSlideIn 0\.35s cubic-bezier\(0\.68, -0\.55, 0\.265, 1\.55\);
\}

@keyframes konataSlideIn \{
    from \{
        opacity: 0;
        transform: translateY\(-12px\) scale\(0\.95\);
    \}
    to \{
        opacity: 1;
        transform: translateY\(0\) scale\(1\);
    \}
\}

/\* Markdown 段落 \*/
\.konata-thinking-content p \{
    margin: 8px 0;
\}
\.konata-thinking-content p:first-child \{
    margin-top: 0;
\}
\.konata-thinking-content p:last-child \{
    margin-bottom: 0;
\}

/\* 粗体 \*/
\.konata-thinking-content strong \{
    font-weight: 700;
    color: #d946a6;
    text-shadow: 0 0 8px rgba\(217, 70, 166, 0\.2\);
\}

/\* 斜体 \*/
\.konata-thinking-content em \{
    font-style: italic;
    opacity: 0\.92;
    color: #ba68c8;
\}

/\* 行内代码 \*/
\.konata-thinking-content code \{
    background: rgba\(255, 182, 193, 0\.15\);
    color: #ec4899;
    padding: 2px 7px;
    border-radius: 5px;
    font-size: 12\.5px;
    font-family: 'Consolas', 'Monaco', monospace;
    border: 1px solid rgba\(255, 182, 193, 0\.25\);
\}

/\* 代码块 \*/
\.konata-thinking-content pre \{
    background: linear-gradient\(135deg, rgba\(255, 182, 193, 0\.08\), rgba\(186, 104, 200, 0\.08\)\);
    border-left: 3px solid rgba\(255, 105, 180, 0\.4\);
    padding: 10px 12px;
    border-radius: 8px;
    overflow-x: auto;
    margin: 10px 0;
    box-shadow: inset 0 1px 3px rgba\(255, 105, 180, 0\.1\);
\}

\.konata-thinking-content pre code \{
    background: none;
    padding: 0;
    font-size: 12px;
    border: none;
\}

/\* 链接 \*/
\.konata-thinking-content a \{
    color: #ff69b4;
    text-decoration: none;
    border-bottom: 2px dotted rgba\(255, 105, 180, 0\.4\);
    transition: all 0\.2s;
    font-weight: 600;
\}

\.konata-thinking-content a:hover \{
    color: #ff1493;
    border-bottom-color: #ff1493;
    text-shadow: 0 0 8px rgba\(255, 20, 147, 0\.3\);
\}

/\* 列表 \*/
\.konata-thinking-content ul,
\.konata-thinking-content ol \{
    margin: 8px 0;
    padding-left: 22px;
\}

\.konata-thinking-content li \{
    margin: 4px 0;
    position: relative;
\}

\.konata-thinking-content li::marker \{
    color: #ff69b4;
\}

/\* 引用块 \*/
\.konata-thinking-content blockquote \{
    border-left: 3px solid rgba\(255, 105, 180, 0\.35\);
    background: rgba\(255, 182, 193, 0\.05\);
    padding: 8px 12px;
    margin: 10px 0;
    border-radius: 0 8px 8px 0;
    font-style: italic;
    color: #9c4a9e;
\}

/\* 标题 \*/
\.konata-thinking-content h1,
\.konata-thinking-content h2,
\.konata-thinking-content h3,
\.konata-thinking-content h4,
\.konata-thinking-content h5,
\.konata-thinking-content h6 \{
    color: #ff69b4;
    font-weight: 700;
    margin: 12px 0 8px 0;
    border-bottom: 1px dashed rgba\(255, 105, 180, 0\.2\);
    padding-bottom: 5px;
\}

\.konata-thinking-content h1 \{ font-size: 18px; \}
\.konata-thinking-content h2 \{ font-size: 16px; \}
\.konata-thinking-content h3 \{ font-size: 15px; \}
\.konata-thinking-content h4 \{ font-size: 14px; \}

/\* 水平线 \*/
\.konata-thinking-content hr \{
    border: none;
    border-top: 2px dashed rgba\(255, 105, 180, 0\.3\);
    margin: 15px 0;
\}

/\* 滚动条美化 \*/
\.konata-thinking-content::-webkit-scrollbar \{
    width: 6px;
\}

\.konata-thinking-content::-webkit-scrollbar-track \{
    background: linear-gradient\(180deg, rgba\(255, 182, 193, 0\.15\), rgba\(186, 104, 200, 0\.15\)\);
    border-radius: 3px;
\}

\.konata-thinking-content::-webkit-scrollbar-thumb \{
    background: linear-gradient\(180deg, #ffb3d9, #ba68c8\);
    border-radius: 3px;
    transition: background 0\.2s;
    box-shadow: inset 0 0 3px rgba\(255, 255, 255, 0\.5\);
\}

\.konata-thinking-content::-webkit-scrollbar-thumb:hover \{
    background: linear-gradient\(180deg, #ff69b4, #d946a6\);
\}

/\* 移动端适配 \*/
@media \(max-width: 480px\) \{
    \.konata-thinking-details \{
        border-radius: 18px;
    \}
    \.konata-thinking-summary \{
        padding: 14px 18px;
        font-size: 14px;
    \}
    \.konata-thinking-content \{
        max-height: 300px;
        padding: 12px 15px;
        font-size: 13px;
    \}
\}

/\* 减弱动画 \*/
@media \(prefers-reduced-motion: reduce\) \{
    \* \{
        animation-duration: 0\.01ms !important;
        transition-duration: 0\.01ms !important;
    \}
    \.konata-bubble,
    \.konata-heart \{
        animation: none !important;
    \}
\}
